changeSet.sql:
INSERT INTO statistic_records (id, stammtisch_id, event_id, actor_user_id, feature, kind, variant, responds_to, source_id, quantity, occurred_at) SELECT ${uuid.fn}, l.stammtisch_id, l.event_id, l.member_id, 'purchase', 'triggered', l.source, NULL, l.id, 1, l.created_at FROM ledger_entries l WHERE l.entry_type = 'purchase' AND NOT EXISTS (SELECT 1 FROM ledger_entries c WHERE c.reverses_entry_id = l.id);
INSERT INTO statistic_records (id, stammtisch_id, event_id, actor_user_id, feature, kind, variant, responds_to, source_id, quantity, occurred_at) SELECT ${uuid.fn}, l.stammtisch_id, NULL, l.member_id, 'top_up', 'triggered', NULL, NULL, l.id, 1, l.created_at FROM ledger_entries l WHERE l.entry_type = 'topup' AND NOT EXISTS (SELECT 1 FROM ledger_entries c WHERE c.reverses_entry_id = l.id);
INSERT INTO statistic_records (id, stammtisch_id, event_id, actor_user_id, feature, kind, variant, responds_to, source_id, quantity, occurred_at) SELECT ${uuid.fn}, b.stammtisch_id, b.event_id, b.actor_id, 'round', 'triggered', b.source, NULL, NULL, b.members, b.occurred_at FROM ( SELECT l.stammtisch_id AS stammtisch_id, l.event_id AS event_id, l.actor_id AS actor_id, l.source AS source, ${batch.key} AS batch_key, COUNT(*) AS members, MIN(l.created_at) AS occurred_at FROM ledger_entries l WHERE l.entry_type = 'purchase' AND l.source IN ('round', 'evening') AND NOT EXISTS (SELECT 1 FROM ledger_entries c WHERE c.reverses_entry_id = l.id) GROUP BY l.stammtisch_id, l.event_id, l.actor_id, l.source, ${batch.key} ) b;
INSERT INTO statistic_records (id, stammtisch_id, event_id, actor_user_id, feature, kind, variant, responds_to, source_id, quantity, occurred_at) SELECT ${uuid.fn}, e.stammtisch_id, e.id, e.owner_id, 'event', 'triggered', NULL, NULL, e.id, 1, e.created_at FROM events e;
INSERT INTO statistic_records (id, stammtisch_id, event_id, actor_user_id, feature, kind, variant, responds_to, source_id, quantity, occurred_at) SELECT ${uuid.fn}, p.stammtisch_id, p.event_id, p.user_id, 'rsvp', 'response', p.rsvp, p.event_id, p.id, 1, COALESCE(p.rsvp_at, p.joined_at) FROM event_participants p WHERE p.rsvp IN ('accepted', 'maybe', 'declined') AND p.user_id IS NOT NULL;
INSERT INTO statistic_records (id, stammtisch_id, event_id, actor_user_id, feature, kind, variant, responds_to, source_id, quantity, occurred_at) SELECT ${uuid.fn}, s.stammtisch_id, s.event_id, s.creator_user_id, 'moment', 'triggered', s.topic_type, NULL, s.id, 1, s.created_at FROM moment_sessions s;
INSERT INTO statistic_records (id, stammtisch_id, event_id, actor_user_id, feature, kind, variant, responds_to, source_id, quantity, occurred_at) SELECT ${uuid.fn}, r.stammtisch_id, s.event_id, r.user_id, 'moment_reaction', 'response', NULL, s.id, r.id, 1, r.created_at FROM moment_responses r JOIN moment_sessions s ON s.id = r.moment_id;
INSERT INTO statistic_records (id, stammtisch_id, event_id, actor_user_id, feature, kind, variant, responds_to, source_id, quantity, occurred_at) SELECT ${uuid.fn}, m.stammtisch_id, s.event_id, m.owner_id, 'moment_media', 'response', m.kind, s.id, m.id, 1, m.created_at FROM moment_media m JOIN moment_sessions s ON s.id = m.moment_id;
INSERT INTO statistic_records (id, stammtisch_id, event_id, actor_user_id, feature, kind, variant, responds_to, source_id, quantity, occurred_at) SELECT ${uuid.fn}, m.stammtisch_id, c.event_id, m.sender_id, 'chat_message', 'triggered', c.type, NULL, m.id, 1, m.created_at FROM chat_messages m JOIN conversations c ON c.id = m.conversation_id WHERE c.type <> 'direct';
INSERT INTO statistic_records (id, stammtisch_id, event_id, actor_user_id, feature, kind, variant, responds_to, source_id, quantity, occurred_at) SELECT ${uuid.fn}, r.stammtisch_id, c.event_id, r.user_id, 'chat_reaction', 'response', c.type, m.id, r.id, 1, r.created_at FROM chat_reactions r JOIN chat_messages m ON m.id = r.message_id JOIN conversations c ON c.id = m.conversation_id WHERE c.type <> 'direct';
INSERT INTO statistic_records (id, stammtisch_id, event_id, actor_user_id, feature, kind, variant, responds_to, source_id, quantity, occurred_at) SELECT ${uuid.fn}, i.stammtisch_id, NULL, i.created_by, 'invite_link', 'triggered', NULL, NULL, i.id, 1, i.created_at FROM member_invites i;
INSERT INTO statistic_records (id, stammtisch_id, event_id, actor_user_id, feature, kind, variant, responds_to, source_id, quantity, occurred_at) SELECT ${uuid.fn}, r.stammtisch_id, NULL, r.user_id, 'invite_join', 'response', NULL, r.invite_id, r.id, 1, r.redeemed_at FROM member_invite_redemptions r;

ALTER TABLE statistic_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE statistic_records FORCE ROW LEVEL SECURITY;
CREATE POLICY stammtisch_isolation ON statistic_records
    USING (current_setting('vereint.rls_bypass', true) = 'on'
           OR stammtisch_id = nullif(current_setting('vereint.stammtisch_id', true), '')::uuid)
    WITH CHECK (current_setting('vereint.rls_bypass', true) = 'on'
           OR stammtisch_id = nullif(current_setting('vereint.stammtisch_id', true), '')::uuid);
